<script setup lang="ts">definePageMeta({layout:'admin'});const {data:response}=await useFetch<any>('/api/admin/analytics/overview');const data=computed(()=>response.value.data)</script>
<template><section class="dashboard"><header><p class="eyebrow">DASHBOARD</p><h1>仪表盘</h1></header><div class="stats"><UCard><small>文章总数</small><strong>{{data.totalPosts}}</strong></UCard><UCard><small>已发布</small><strong>{{data.publishedPosts}}</strong></UCard><UCard><small>全站访问量</small><strong>{{data.totalViews}}</strong></UCard></div><div class="columns"><UCard><template #header><strong>浏览量 Top 5</strong></template><div class="rows"><div v-for="post in data.topPosts" :key="post.id"><NuxtLink :to="`/admin/posts/${post.id}/edit`">{{post.title}}</NuxtLink><span>{{post.viewCount}}</span></div><p v-if="!data.topPosts.length">暂无文章</p></div></UCard><UCard><template #header><strong>最近编辑</strong></template><div class="rows"><div v-for="post in data.recentPosts" :key="post.id"><NuxtLink :to="`/admin/posts/${post.id}/edit`">{{post.title}}</NuxtLink><span>{{new Date(post.updatedAt).toLocaleDateString('zh-CN')}}</span></div></div></UCard></div></section></template>
<style scoped>.dashboard{display:grid;gap:24px}.dashboard h1{margin:0}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.stats small,.stats strong{display:block}.stats small{color:var(--color-text-secondary)}.stats strong{margin-top:10px;font-size:28px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}.rows{display:grid}.rows>div{display:flex;justify-content:space-between;gap:16px;padding:11px 0;border-bottom:1px solid var(--color-border);font-size:12px}.rows span{color:var(--color-text-secondary)}@media(max-width:700px){.stats,.columns{grid-template-columns:1fr}}</style>
